    "mechanism": "위산을 직접 중화하고 화학적 자극에 대한 점막 보호 작용을 수행(복용 즉시 효과가 빠르나 위에 제산제가 남아있는 동안만 일시적 작용). 히드로탈시트(Al2Mg6(OH)16CO3·4H2O)는 격자층 구조로 위산 정도에 따라 중화작용이 조절되며 점막을 보호하고, 알마게이트(Al2Mg6(OH)14(CO3)2·4H2O)는 결정구조로 열 안정성과 높은 중화력을 가짐",
    "contraindication": "• 신부전·투석 환자: 마그네슘(고마그네슘혈증), 알루미늄(신경독성, 빈혈, 뇌 축적 및 알츠하이머병 관련성 보고) 축적 주의. 히드로탈시트·알마게이트·알디옥사는 명칭만으로 알루미늄 함유 여부를 알기 어려우므로 성분 확인 필수\n• 구연산(citrate) 함유 약물·식품과 병용 금지(알루미늄 흡수 약 50배 증가)\n• 상호작용: 테트라사이클린계(독시사이클린, 미노사이클린), 뉴퀴놀론계(씨프로플록사신, 레보플록사신)와 착화합물 형성으로 흡수 저해; 위 산도 변화로 아졸계 항진균제·아타자나비어·철분제 흡수 저해 → 시간 간격 두고 복용\n• 임부: 알루미늄염·마그네슘염 제산제는 임부에게 비교적 안전\n• 연령: 겔포스엠현탁액® 3개월 미만 금기(1세 미만 원칙적 금기), 알마겔 12세 이상, 겔포스엘/복합탈시드 15세 이상",
