    "frontQuestion": "설사 환자 문진(Step 1)에서 반드시 확인해야 할 설사 유발 약물(표 22-1), 기저질환 위험군, 그리고 즉시 병원 진료를 권고해야 하는 Red Flag 기준(Step 2)은 무엇인가?",
    "mainIngredient": "해당 없음 (문진 및 진료 의뢰 의사결정 알고리즘)",
    "mechanism": "잦은 설사는 수분 및 전해질(특히 칼륨) 손실과 영양소 흡수 저하를 유발한다. ① 부정맥 환자: 혈중 칼륨 저하로 항부정맥제 작용 변동 및 QT 연장 약물(sulpiride, azithromycin, trazodone 등) 이상반응 위험 증가. ② 심부전·심방세동 환자: 디기탈리스(digitalis) 복용 중 혈중 칼륨 저하로 디기탈리스 중독증상(구역질, 설사, 두통, 맥박 불안정) 유발 용이. ③ 당뇨병 환자: 혈당강하제·인슐린 사용 중 영양소 흡수 방해로 저혈당 발생 가능.",
