    "algorithmFlow": "수진 대상이 아니며 감염 확산 우려가 적다는 전제 하에 증상 양상으로 OTC 선택: ① 물설사(장 내 수분 정체 및 흡수력 저하 위주, 발열·복통 경미, 대변 악취 미미, 물만 먹어도 토할 것 같은 울렁거림) → 장관운동억제제(로페라미드/리다미딘 단일제) 적합. ② 이급후중성 설사(대장증상 유사, 아랫배·항문 가장자리 끌어당기는 통증과 잦은 변의, 시원치 않고 변 양 적음, 물설사보다 발열·복통 상대적으로 심하고 진흙·점액질 모양, 악취 가능성) → 장관운동억제제 단일제 회피, 장내 방부 항균제(니푸록사지드, 크레오소트) 또는 소량 로페라미드+장내 살균성분 복합제, 스멕타이트, 진경제 병용 고려. ③ 물설사·이급후중성 구분 모호 시 → 로페라미드 함량이 낮고 아크리놀·베르베린·유산균이 배합된 로페라미드 복합제 고려.",
