    "contraindication": "금기: 2세 미만 영아, 심한 복통, 이급후중성/혈변/점액변/고열을 동반한 세균성 설사, C. difficile 위막성 대장염 및 궤양성대장염 급성·중증형(독성거대결장, 마비성 장폐색 유발 위험), 스코폴라민 단일제와의 병용(장관운동 억제효과 과도, Pretest Q1). 이상반응: 심한 변비, 졸음, 어지럼증. 과량 복용 시 QT 간격 연장, 중대한 심실부정맥, 사망 사례 보고.",
