    "counselingTip": "① 수분 보충: 경구용 수분 보충제를 끓인 물로 조제해 한 번에 많이 마시지 말고 조금씩 자주 마시도록 지도한다. 보충제 제조가 어렵다면 이온음료보다 보리차를 권하고, 이온음료밖에 없다면 차선책으로 조심스럽게 섭취하게 한다. ② 식이요법: 영양 보충보다 위장을 쉬게 하는 것을 우선으로 하여 기름지지 않고 소화가 잘되는 부드럽게 지은 밥과 된장국 등 섬유소가 적은 음식을 조금씩 자주 섭취한다. ③ 생활습관: 평소 음식을 잘 익혀 먹고 깨끗이 씻어 먹도록 교육한다."
