    "algorithmFlow": "대상자(주로 젊은 사람, 스트레스·감정 변화 관련, 술·고지방 음식 다량 섭취자 포함) 및 양상(급성, 심한 불쾌감과 복통 동반, 변이 조각나 토끼똥처럼 나오거나 가늘게 나옴) 확인 → 경련성 변비로 판단 → 장관조절제(트리메부틴 등)로 경련 억제 + 점액 보충 + 대장 자극성이 덜한 하제(팽윤성하제 또는 수산화마그네슘제제) + 이담제(UDCA) 병용 고려 (자극성하제 회피)",
