    "frontQuestion": "고령자, 신장질환자, 심장질환자, 치질 동반 환자, 그리고 4~5일 이상 오래된 변비 환자 각각에서 1차 선택약과 금기 약물은?",
    "mainIngredient": "- 고령자 1차: 팽윤성하제 (차전자피)\n- 치질 동반자: 도큐세이트 함유 하제 (둘코락스에스, 비코그린에스 등)\n- 4~5일 이상 오래된 변비: 글리세린 관장약(성광관장약®, 그린관장약®) 우선 사용 후 경구용 변비약 복용",
    "mechanism": "고령자는 노화 자체보다 퇴행성 변화(칼로리·섬유질·수분 섭취 감소), 활동 감소, 만성질환(파킨슨병·당뇨병·우울증), 변비 유발 약물 증가가 원인. 오래된 변비는 직장에 굳은 변괴가 경구 하제의 통과와 작용을 방해하므로 관장이 먼저 필요함.",
    "contraindication": "- 신장질환자: 수산화마그네슘 등 염류성하제 금기(고마그네슘혈증 위험, Pretest Q4)\n- 심장질환자: 관장 등 하제 추천 안 함(혈압 변화로 악화, Pretest Q5), 자극성하제 장기 시 심실부정맥 위험\n- 고령자: 탈진·병상 와병·장폐색 시 팽윤성하제 금기, 신기능 저하·전해질 민감으로 수산화마그네슘 주의\n- 치질 환자: 알로에, 대황, 글리세린 관장약 금기",
    "counselingTip": "고령 환자는 먼저 복용 중인 만성질환 약물 중 변비 유발 약이 있는지 점검하고 대체 가능 여부를 안내한다. 4~5일 이상 변을 못 봐 변이 딱딱하게 굳은 환자에게 경구제만 주면 효과가 떨어지므로 관장 후 경구제를 쓰도록 지도한다."
