    "algorithmFlow": "1) 해부학적 기준 확인: 항문은 약 4~5 cm 길이로 외부괄약근(수의근)과 내부괄약근(불수의근)으로 구성되며, 동·정맥이 연결되고 직장점막 흡수 약물은 간을 경유하지 않고 바로 전신 흡수됨. 항문관 안쪽 1.5~2 cm의 치상선(pectinate line, anorectal junction)을 기준으로 상부(감각신경섬유 거의 없음, 모르가니주 존재)와 하부(감각신경섬유 분포)로 구분.\n2) 주증상별 감별: ① 통증 거의 없이 선홍색 출혈·배변곤란 → 내치핵(치상선 위) ② 심한 통증·울혈·배변 공포감 → 외치핵(치상선 아래) ③ 갑작스런 극심한 찢어지는 통증(배변 후 1~2시간 지속 가능) 및 선홍색 출혈 → 치열(치상선 하측 항문상피 파열) ④ 항문샘 감염 후 농양·구멍(외구)·반복적 고름/분비물 및 고열 → 항문주위농양/치루 ⑤ 가려움과 피부 태선화 → 항문소양증.",
