    "redFlag": "Step 2 의사 진료를 권해야 하는 9가지 Red Flag:\n1) 12세 미만 소아가 항문질환 증상을 보이고 1주일 이상 생활요법으로 개선되지 않는 경우\n2) 3도 내지 4도 내치핵 의심 또는 고름·분비물 동반(치루 시사)\n3) 출혈 및 통증이 아주 심하거나 출혈 시 피가 약간 검은색을 띠는 경우\n4) 치열이 만성적이거나 측방에 위치한 경우\n5) 직장탈이 의심되는 경우\n6) 발열 및 심한 통증 호소(환부 염증·전신감염·치루 의심)\n7) 급격하게 변이 가늘어지고 몸무게가 비정상적으로 감소(대장암 등 시사)\n8) 항문질환용 일반의약품을 1주일 이상 사용하였으나 증상이 개선되지 않는 경우\n9) 대장암·직장암 등의 가족력이 있는 경우",
    "frontQuestion": "약국에서 항문질환 환자 문진 시 반드시 확인해야 할 7가지 항목과, 즉시 병원 진료를 권고해야 하는 9가지 Red Flag는?",
