    "mainIngredient": "박테리아배양액 단일제 (포스테리산연고®, 포스테리산좌제®): 성인 1일 2회. (항문대장균 배양액에서 추출한 세포내용물·대사물을 채취해 약독화시킨 표준화 물질).",
    "mechanism": "국소 면역반응을 자극하고 항체 형성 및 백혈구 활성을 증진시켜 항문세균에 대한 적응력을 높이며, 치핵 부위에 새로운 결합조직 형성을 촉진하여 치질을 치료함.",
    "contraindication": "보존제로 페놀을 함유하여 페놀 알레르기 환자에게는 적용 불가. 다른 약물과의 특별한 상호작용이 없는 것이 큰 장점.",
