    "algorithmFlow": "1) 한방·생약 제제를 희망하거나 항문열창(치열)으로 인한 피부염·상처 진정이 필요한 경우 → 자운고제제 선택.\n2) 배변 시 마찰로 인한 출혈·통증 감소 및 말초순환 개선 → 오일성분(상어간유, 레티놀유) 및 토코페롤 함유 외용제 선택.",
