    "counselingTip": "치열이나 한방 외용제를 선호하는 환자에게 자운고제제는 소염·피부재생에 좋은 선택지이며, 배변 전후 마찰 통증이 심할 때는 오일 성분이 배합된 연고(푸레파연고 등)가 윤활에 도움을 줄 수 있음."
