    "mechanism": "활성 플라보노이드(flavonoid)를 함유하여 정맥혈관의 긴장도를 높여 혈액순환 및 혈관강화를 돕고, 이상 항진된 혈관 투과성을 감소시켜 소염 및 부종완화 작용을 나타냄. 이를 통해 치질에 의한 출혈, 통증, 가려움증을 완화하고 외상 또는 수술 후 부종·염증 완화에도 사용됨(주로 급성 치질에 유효).",
