    "mainIngredient": "1) 을자탕건조엑스 (크라시에을자탕엑스세립®): 당귀, 감초, 승마, 대황, 시호, 황금 구성. 성인 1일 6 g, 2~3회 분복. 적응증: 치핵, 치열, 변비 증상.\n2) 치지래과립® (Tocopherol Acetate + 서양칠엽수종자엑스 + 목단피건조엑스 + 자근건조엑스): 성인 1회 1포, 1일 2회. 적응증: 치핵, 항문열상, 치출혈. [연령제한] 15세 미만 금기.",
    "mechanism": "을자탕은 대황의 사하 작용 등으로 변비 동반 치질에 효과적임. 치지래과립®은 서양칠엽수종자(염증 억제·혈액순환 개선), 목단피(진정·혈액순환), 자근(혈액순환·항염), 토코페롤(항산화·세포손상 방지·순환 개선)의 복합 작용으로 항문주위 말초 혈액순환 개선 및 염증 완화.",
    "contraindication": "1) 을자탕: 임부 금기(대황의 자궁수축 및 장기충혈 작용), 수유부 금기(대황 중 안트라퀴논 유도체가 모유로 이행해 유아에게 설사 유발), 다른 설사유도약(완하제)과 병용금기, 이미 변비약 복용 중이거나 설사가 잦은 환자 부적절.\n2) 치지래과립®: 15세 미만, 알레르기 환자 금기.",
