    "algorithmFlow": "Step 3 (배변 양상 및 주증상에 따른 OTC 선택 알고리즘):\n1) 설사형 IBS:\n- 배변 횟수/성상 조절: 로페라미드 단기 사용 가능\n- 복통·경련 동반 시: 항콜린제(디싸이클로민, 부틸스코폴라민 등) 또는 트리메부틴(지사제와 병용 가능) 권고\n2) 변비형 IBS:\n- 1차 선택: 팽윤성하제(차전자피 제제)로 복통 및 변비 경감 기대\n- 팽윤성하제 효과 불충분 시: 삼투성하제(수산화마그네슘, 락툴로오스) 또는 대변연화제(도큐세이트) 추천 가능 (단, 복통 미개선 시 트리메부틴 병용 고려)\n- 금기/주의: 자극성하제(비사코딜 등) 사용 금지, 항콜린제는 변비 악화 우려로 사용 주의\n3) 변비형 또는 설사·변비 교대형 IBS (심한 복통·복부팽만 동반):\n- 1차 선택: 트리메부틴 제제(양면작용)\n- 금기/주의: 로페라미드 사용 금지(변비 유발), 항콜린제 사용 주의(변비 악화)\n4) 공통 보조요법: 정장제(프로바이오틱스) 꾸준한 복용 권고",
    "redFlag": "일반의약품을 일주일 이상 복용해도 증상이 개선되지 않거나, 진경제 일주일 이상 복용에도 차도가 없는 경우 의사 진료 권고(정신신경계 약물 처방 필요 가능).",
    "frontQuestion": "설사형, 변비형, 설사·변비 교대형 과민성대장증후군 환자 각각에 대한 OTC 1차 선택 약물(Drug of Choice)과 피해야 할 약물군은 어떻게 구분되는가?",
    "mainIngredient": "설사형: Loperamide(단기), 항콜린제, Trimebutine / 변비형: 차전자피(팽윤성하제), 불충분 시 Lactulose·수산화마그네슘·Docusate(+필요 시 Trimebutine) / 교대형: Trimebutine / 공통 보조: 프로바이오틱스(정장제)",
    "mechanism": "IBS의 약물 선택은 호소 증상과 배변 양상에 따르며, 과다 수축된 위장관 평활근 이완(진경제), 장관 운동 정상화(엔케팔린 효능제), 수분 보유 및 대변 용적 증가(팽윤성·삼투성하제), 장내 이상발효 경감(정장제)을 통해 증상을 완화하고 삶의 질을 개선함.",
    "contraindication": "변비형 및 교대형 IBS에 로페라미드 사용 금지. 변비형 IBS에 자극성하제 사용 금지(경련성 통증 및 장기 사용 시 장신경 손상). 변비형·교대형 IBS에 항콜린제 사용 주의(변비 악화 위험).",
    "counselingTip": "환자에게 우선 식단·운동습관 등 생활패턴 개선과 스트레스 해결을 권유하고, 아형에 맞는 약물을 선택하되 일주일 내 호전 없으면 병의원 진료를 받도록 지도함."
