    "mainIngredient": "Loperamide HCl (예: 로프민캡슐®) / 성인 용법·용량: 초회량 4 mg, 유지량 2 mg (1일 최대투여량 16 mg) / 연령제한: 소아 IBS 환자는 의사 진료 대상(표 25-1 성인 기준).",
    "mechanism": "장관 운동을 억제하는 지사제로, 단기 사용 시 대변 성상을 호전시키고 배변 횟수를 감소시킴. 단, 복통 자체를 개선하는 진경 작용은 없음.",
    "contraindication": "변비형 IBS 환자 및 설사와 변비의 교대형 IBS 환자에게 사용 금지(심한 변비 유발 위험성이 큼). 일반 IBS 환자에서도 때때로 심한 변비를 유발할 수 있으므로 주의 필요.",
    "counselingTip": "정답(Q1): T. 단기요법 또는 출근·장거리 여행 전날 예방적/조절 목적 복용은 효과적이나, 설사·변비 교대형 환자에는 변비 유발 위험으로 사용하지 않도록 반드시 배변 양상을 문진 후 투약함. 복통이 주증상일 경우 단독으로는 복통이 개선되지 않음을 안내함."
