// ============================================================================
// 유틸리티 & 정규화 함수
// ============================================================================
const STORAGE_KEYS = {
  STARRED: 'pharm_pwa_starred_v1',
  MASTERED: 'pharm_pwa_mastered_v1',
  CUSTOM_CARDS: 'pharm_pwa_custom_cards_v1',
  DAILY_VIEWS: 'pharm_pwa_daily_views_v1',
};

function safeGetStorage(key, fallback) {
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function safeSetStorage(key, value) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // 저장 공간 제한 등 예외 무시
  }
}

function getTodayKey() {
  const now = new Date();
  const y = now.getFullYear();
  const m = String(now.getMonth() + 1).padStart(2, '0');
  const d = String(now.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function normalizeFlow(flow) {
  if (Array.isArray(flow)) return flow.filter(Boolean).map(String);
  if (typeof flow === 'string') {
    return flow
      .split(/\s*(?:→|->|\n|>)\s*/)
      .map((s) => s.trim())
      .filter(Boolean);
  }
  return [];
}

function normalizeCard(raw, idx) {
  if (!raw || typeof raw !== 'object') return null;
  const id = String(raw.id || `card-${idx}-${raw.subCategory || raw.chapter || 'item'}`);
  return {
    id,
    chapter: String(raw.chapter || raw.대단원 || '기타 단원'),
    subCategory: String(raw.subCategory || raw.세부질환 || raw.disease || `항목 ${idx + 1}`),
    question: String(raw.question || raw.frontQuestion || raw.질문 || `${raw.subCategory || '해당 질환'}의 핵심 감별 포인트와 복약지도는?`),
    hint: String(raw.hint || raw.frontHint || raw.힌트 || '알고리즘 흐름과 금기사항을 떠올려 보세요.'),
    algorithmFlow: normalizeFlow(raw.algorithmFlow || raw.감별흐름도 || raw.flow),
    redFlag: String(raw.redFlag || raw.레드플래그 || raw.경고 || ''),
    mainIngredient: String(raw.mainIngredient || raw.activeIngredient || raw.ingredients || raw.주성분 || '-'),
    mechanism: String(raw.mechanism || raw.기전 || '-'),
    contraindications: String(raw.contraindications || raw.contraindication || raw.drugInteractions || raw.병용금기 || '-'),
    counseling: String(raw.counseling || raw.counselingTip || raw.medicationGuide || raw.복약지도 || '-'),
  };
}

export default function App() {
  // --------------------------------------------------------------------------
  // 상태 관리
  // --------------------------------------------------------------------------
  const [activeTab, setActiveTab] = useState('algorithm'); // 'algorithm' | 'flashcard' | 'search' | 'backup'
  const [customCards, setCustomCards] = useState(() => safeGetStorage(STORAGE_KEYS.CUSTOM_CARDS, []));
  const [starredIds, setStarredIds] = useState(() => safeGetStorage(STORAGE_KEYS.STARRED, []));
  const [masteredIds, setMasteredIds] = useState(() => safeGetStorage(STORAGE_KEYS.MASTERED, []));
  const [dailyViewData, setDailyViewData] = useState(() => {
    const saved = safeGetStorage(STORAGE_KEYS.DAILY_VIEWS, null);
    const today = getTodayKey();
    if (saved && saved.date === today && Array.isArray(saved.viewedIds)) {
      return saved;
    }
    return { date: today, viewedIds: [] };
  });

  // 알고리즘 맵 상태
  const [selectedChapter, setSelectedChapter] = useState('전체');
  const [expandedIds, setExpandedIds] = useState({});

  // 플래시카드 상태
  const [fcChapter, setFcChapter] = useState('전체');
  const [onlyStarred, setOnlyStarred] = useState(false);
  const [fcIndex, setFcIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [showHint, setShowHint] = useState(false);

  // 검색 상태
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedSearchCard, setSelectedSearchCard] = useState(null);

  // JSON 추가/백업 상태
  const [jsonInput, setJsonInput] = useState('');
  const [importMode, setImportMode] = useState('append'); // 'append' | 'replace'
  const [toast, setToast] = useState(null);
  const [confirmResetOpen, setConfirmResetOpen] = useState(false);

  // --------------------------------------------------------------------------
  // 통합 카드 데이터 & 파생 값
  // --------------------------------------------------------------------------
  const allCards = useMemo(() => {
    const base = Array.isArray(cardsData) ? cardsData : [];
    const custom = Array.isArray(customCards) ? customCards : [];
    const merged = [...base, ...custom];
    const seen = new Set();
    const result = [];
    merged.forEach((item, idx) => {
      const normalized = normalizeCard(item, idx);
      if (!normalized) return;
      let uniqueId = normalized.id;
      if (seen.has(uniqueId)) {
        uniqueId = `${uniqueId}-${idx}`;
      }
      seen.add(uniqueId);
      result.push({ ...normalized, id: uniqueId });
    });
    return result;
  }, [customCards]);

  const chapters = useMemo(() => {
    const set = new Set(allCards.map((c) => c.chapter));
    return ['전체', ...Array.from(set)];
  }, [allCards]);

  const starredSet = useMemo(() => new Set(starredIds), [starredIds]);
  const masteredSet = useMemo(() => new Set(masteredIds), [masteredIds]);

  // localStorage 동기화
  useEffect(() => {
    safeSetStorage(STORAGE_KEYS.STARRED, starredIds);
  }, [starredIds]);

  useEffect(() => {
    safeSetStorage(STORAGE_KEYS.MASTERED, masteredIds);
  }, [masteredIds]);

  useEffect(() => {
    safeSetStorage(STORAGE_KEYS.CUSTOM_CARDS, customCards);
  }, [customCards]);

  useEffect(() => {
    safeSetStorage(STORAGE_KEYS.DAILY_VIEWS, dailyViewData);
  }, [dailyViewData]);

  // 토스트 알림 헬퍼
  const showToast = (message, type = 'success') => {
    setToast({ message, type });
    setTimeout(() => {
      setToast((prev) => (prev?.message === message ? null : prev));
    }, 2800);
  };

  // 토글 함수
  const toggleStar = (id, e) => {
    if (e) e.stopPropagation();
    setStarredIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const toggleMastered = (id, e) => {
    if (e) e.stopPropagation();
    setMasteredIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const markCardViewedToday = (id) => {
    if (!id) return;
    const today = getTodayKey();
    setDailyViewData((prev) => {
      const baseIds = prev.date === today ? prev.viewedIds : [];
      if (baseIds.includes(id)) return prev.date === today ? prev : { date: today, viewedIds: baseIds };
      return { date: today, viewedIds: [...baseIds, id] };
    });
  };

  // --------------------------------------------------------------------------
  // 알고리즘 맵 필터링
  // --------------------------------------------------------------------------
  const algoCards = useMemo(() => {
    if (selectedChapter === '전체') return allCards;
    return allCards.filter((c) => c.chapter === selectedChapter);
  }, [allCards, selectedChapter]);

  const toggleExpand = (id) => {
    setExpandedIds((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const expandAllAlgo = () => {
    const next = {};
    algoCards.forEach((c) => {
      next[c.id] = true;
    });
    setExpandedIds((prev) => ({ ...prev, ...next }));
  };

  const collapseAllAlgo = () => {
    const next = { ...expandedIds };
    algoCards.forEach((c) => {
      next[c.id] = false;
    });
    setExpandedIds(next);
  };

  // --------------------------------------------------------------------------
  // 플래시카드 필터링 & 이동
  // --------------------------------------------------------------------------
  const flashcardPool = useMemo(() => {
    return allCards.filter((c) => {
      if (fcChapter !== '전체' && c.chapter !== fcChapter) return false;
      if (onlyStarred && !starredSet.has(c.id)) return false;
      return true;
    });
  }, [allCards, fcChapter, onlyStarred, starredSet]);

  useEffect(() => {
    setFcIndex(0);
    setIsFlipped(false);
    setShowHint(false);
  }, [fcChapter, onlyStarred]);

  useEffect(() => {
    if (activeTab === 'flashcard' && flashcardPool[fcIndex]) {
      markCardViewedToday(flashcardPool[fcIndex].id);
    }
  }, [activeTab, fcIndex, flashcardPool]);

  const currentFlashcard = flashcardPool[fcIndex] || null;

  const handleFlipCard = () => {
    setIsFlipped((prev) => !prev);
  };

  const handleNextCard = () => {
    if (flashcardPool.length === 0) return;
    setIsFlipped(false);
    setShowHint(false);
    setFcIndex((prev) => (prev + 1) % flashcardPool.length);
  };

  const handlePrevCard = () => {
    if (flashcardPool.length === 0) return;
    setIsFlipped(false);
    setShowHint(false);
    setFcIndex((prev) => (prev - 1 + flashcardPool.length) % flashcardPool.length);
  };

  // --------------------------------------------------------------------------
  // 성분·증상 검색
  // --------------------------------------------------------------------------
  const searchResults = useMemo(() => {
    const q = searchQuery.trim().toLowerCase();
    if (!q) return allCards;
    return allCards.filter((c) => {
      const haystack = [
        c.chapter,
        c.subCategory,
        c.question,
        c.hint,
        c.mainIngredient,
        c.mechanism,
        c.contraindications,
        c.counseling,
        c.redFlag,
        ...c.algorithmFlow,
      ]
        .join(' ')
        .toLowerCase();
      return haystack.includes(q);
    });
  }, [allCards, searchQuery]);

  // --------------------------------------------------------------------------
  // JSON 추가 / 백업 기능
  // --------------------------------------------------------------------------
  const handleImportJson = () => {
    const trimmed = jsonInput.trim();
    if (!trimmed) {
      showToast('붙여넣을 JSON 데이터를 입력해 주세요.', 'error');
      return;
    }
    try {
      const parsed = JSON.parse(trimmed);
      const arr = Array.isArray(parsed) ? parsed : [parsed];
      const valid = arr.filter((item) => item && typeof item === 'object');
      if (valid.length === 0) {
        showToast('유효한 카드 객체 배열이 아닙니다.', 'error');
        return;
      }
      if (importMode === 'replace') {
        setCustomCards(valid);
        showToast(`추가 데이터 ${valid.length}개로 교체했습니다.`);
      } else {
        setCustomCards((prev) => [...prev, ...valid]);
        showToast(`카드 ${valid.length}개를 기존 목록에 이어 붙였습니다.`);
      }
      setJsonInput('');
    } catch {
      showToast('JSON 문법 오류입니다. 대괄호([ ])와 따옴표를 확인해 주세요.', 'error');
    }
  };

  const handleCopyAllJson = async () => {
    const payload = JSON.stringify(allCards, null, 2);
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        await navigator.clipboard.writeText(payload);
        showToast('전체 카드 JSON을 클립보드에 복사했습니다.');
        return;
      }
    } catch {
      // fallback below
    }
    try {
      const ta = document.createElement('textarea');
      ta.value = payload;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      showToast('전체 카드 JSON을 클립보드에 복사했습니다.');
    } catch {
      showToast('복사에 실패했습니다. 파일 다운로드를 이용해 주세요.', 'error');
    }
  };

  const handleDownloadBackup = () => {
    const backupPayload = {
      exportedAt: new Date().toISOString(),
      cards: allCards,
      progress: {
        starredIds,
        masteredIds,
        dailyViewData,
      },
    };
    const blob = new Blob([JSON.stringify(backupPayload, null, 2)], {
      type: 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `pharm-study-backup-${getTodayKey()}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('전체 데이터 및 학습 기록 백업 파일을 다운로드했습니다.');
  };

  const handleResetProgress = () => {
    setStarredIds([]);
    setMasteredIds([]);
    setDailyViewData({ date: getTodayKey(), viewedIds: [] });
    setConfirmResetOpen(false);
    showToast('다시보기 및 암기완료 학습 기록을 초기화했습니다.');
  };

  // --------------------------------------------------------------------------
  // 렌더링
  // --------------------------------------------------------------------------
  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans pb-24">
      {/* 토스트 알림 */}
      {toast && (
        <div className="fixed top-4 left-1/2 -translate-x-1/2 z-50 w-[92%] max-w-md pointer-events-none">
          <div
            className={`px-4 py-3 rounded-xl shadow-lg border text-sm font-medium flex items-center gap-2.5 ${
              toast.type === 'error'
                ? 'bg-red-600 text-white border-red-700'
                : 'bg-slate-900 text-white border-slate-800'
            }`}
          >
            {toast.type === 'error' ? (
              <AlertTriangle className="w-4 h-4 shrink-0" />
            ) : (
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
            )}
            <span>{toast.message}</span>
          </div>
        </div>
      )}

      {/* 상단 고정 헤더 & 모드 전환 탭 */}
      <header className="sticky top-0 z-30 bg-white/95 backdrop-blur border-b border-slate-200">
        <div className="max-w-2xl mx-auto px-4 pt-3 pb-2.5">
          <div className="flex items-center justify-between mb-2.5">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-xl bg-teal-600 text-white flex items-center justify-center shadow-sm">
                <Pill className="w-4 h-4" />
              </div>
              <div>
                <h1 className="text-base font-bold tracking-tight text-slate-900 leading-tight">
                  약학 국시 알고리즘 암기장
                </h1>
                <p className="text-[11px] text-slate-500">
                  총 {allCards.length}장 · 암기완료 {masteredIds.length}장 · ★ {starredIds.length}장
                </p>
              </div>
            </div>
            <div className="flex items-center gap-1.5 text-xs font-medium bg-teal-50 text-teal-700 px-2.5 py-1 rounded-full border border-teal-100">
              <Eye className="w-3.5 h-3.5" />
              <span>오늘 {dailyViewData.viewedIds.length}장</span>
            </div>
          </div>

          {/* 상단 탭 전환: [단원별 알고리즘 맵] vs [플래시카드 암기] */}
          <div className="grid grid-cols-2 gap-1.5 bg-slate-100 p-1 rounded-xl">
            <button
              type="button"
              onClick={() => setActiveTab('algorithm')}
              className={`py-2 px-3 rounded-lg text-xs sm:text-sm font-semibold flex items-center justify-center gap-1.5 transition-all ${
                activeTab === 'algorithm'
                  ? 'bg-white text-teal-700 shadow-sm'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              <GitBranch className="w-4 h-4" />
              <span>단원별 알고리즘 맵</span>
            </button>
            <button
              type="button"
              onClick={() => setActiveTab('flashcard')}
              className={`py-2 px-3 rounded-lg text-xs sm:text-sm font-semibold flex items-center justify-center gap-1.5 transition-all ${
                activeTab === 'flashcard'
                  ? 'bg-white text-teal-700 shadow-sm'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              <Layers className="w-4 h-4" />
              <span>플래시카드 암기</span>
            </button>
          </div>
        </div>
      </header>

      {/* 메인 컨텐츠 */}
      <main className="max-w-2xl mx-auto px-4 pt-4">
        {/* ================================================================
            1. 단원별 알고리즘 맵 모드
           ================================================================ */}
        {activeTab === 'algorithm' && (
          <section className="space-y-4">
            {/* 대단원 선택 칩 */}
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-1.5 overflow-x-auto pb-1 no-scrollbar">
                {chapters.map((ch) => (
                  <button
                    key={ch}
                    type="button"
                    onClick={() => setSelectedChapter(ch)}
                    className={`shrink-0 px-3 py-1.5 rounded-full text-xs font-semibold border transition-colors ${
                      selectedChapter === ch
                        ? 'bg-teal-600 text-white border-teal-600 shadow-sm'
                        : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    {ch}
                  </button>
                ))}
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <button
                  type="button"
                  onClick={expandAllAlgo}
                  className="text-[11px] font-medium text-teal-700 bg-teal-50 px-2 py-1 rounded-lg hover:bg-teal-100"
                >
                  모두 펼침
                </button>
                <button
                  type="button"
                  onClick={collapseAllAlgo}
                  className="text-[11px] font-medium text-slate-600 bg-slate-100 px-2 py-1 rounded-lg hover:bg-slate-200"
                >
                  접기
                </button>
              </div>
            </div>

            {/* 세부 질환별 아코디언 카드 */}
            <div className="space-y-3">
              {algoCards.map((card) => {
                const isOpen = !!expandedIds[card.id];
                const isStarred = starredSet.has(card.id);
                const isMastered = masteredSet.has(card.id);

                return (
                  <article
                    key={card.id}
                    className={`bg-white rounded-2xl border transition-all overflow-hidden ${
                      isMastered ? 'border-emerald-200 shadow-sm' : 'border-slate-200 shadow-sm'
                    }`}
                  >
                    {/* 아코디언 헤더 */}
                    <div
                      onClick={() => toggleExpand(card.id)}
                      role="button"
                      tabIndex={0}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          toggleExpand(card.id);
                        }
                      }}
                      className="p-4 flex items-start justify-between gap-3 cursor-pointer hover:bg-slate-50/70 transition-colors"
                    >
                      <div className="min-w-0 flex-1">
                        <div className="flex flex-wrap items-center gap-1.5 mb-1">
                          <span className="inline-block text-[11px] font-semibold px-2 py-0.5 rounded-md bg-teal-50 text-teal-700 border border-teal-100">
                            {card.chapter}
                          </span>
                          {isMastered && (
                            <span className="inline-flex items-center gap-0.5 text-[11px] font-semibold px-2 py-0.5 rounded-md bg-emerald-50 text-emerald-700 border border-emerald-200">
                              <Check className="w-3 h-3" /> 암기완료
                            </span>
                          )}
                        </div>
                        <h2 className="text-base font-bold text-slate-900 leading-snug">
                          {card.subCategory}
                        </h2>
                        <p className="text-xs text-slate-500 mt-1 line-clamp-1">
                          주성분: {card.mainIngredient}
                        </p>
                      </div>

                      <div className="flex items-center gap-1.5 shrink-0">
                        <button
                          type="button"
                          onClick={(e) => toggleStar(card.id, e)}
                          aria-label="다시보기 즐겨찾기"
                          className={`p-2 rounded-xl border transition-colors ${
                            isStarred
                              ? 'bg-amber-50 border-amber-200 text-amber-500'
                              : 'bg-slate-50 border-slate-200 text-slate-400 hover:text-amber-500'
                          }`}
                        >
                          <Star className={`w-4 h-4 ${isStarred ? 'fill-amber-400' : ''}`} />
                        </button>
                        <button
                          type="button"
                          onClick={(e) => toggleMastered(card.id, e)}
                          aria-label="암기완료 체크"
                          className={`p-2 rounded-xl border transition-colors ${
                            isMastered
                              ? 'bg-emerald-50 border-emerald-200 text-emerald-600'
                              : 'bg-slate-50 border-slate-200 text-slate-400 hover:text-emerald-600'
                          }`}
                        >
                          <CheckCircle2 className="w-4 h-4" />
                        </button>
                        <div className="p-1.5 text-slate-400">
                          {isOpen ? (
                            <ChevronUp className="w-5 h-5" />
                          ) : (
                            <ChevronDown className="w-5 h-5" />
                          )}
                        </div>
                      </div>
                    </div>

                    {/* 아코디언 바디 */}
                    {isOpen && (
                      <div className="px-4 pb-4 pt-1 border-t border-slate-100 space-y-3">
                        {/* 감별 흐름도 (algorithmFlow) */}
                        <div className="bg-slate-50 rounded-xl p-3 border border-slate-200/80">
                          <div className="flex items-center gap-1.5 text-xs font-bold text-slate-700 mb-2">
                            <GitBranch className="w-3.5 h-3.5 text-teal-600" />
                            <span>감별 흐름도 (Algorithm Flow)</span>
                          </div>
                          {card.algorithmFlow.length > 0 ? (
                            <div className="space-y-1.5">
                              {card.algorithmFlow.map((step, i) => (
                                <div key={i} className="flex items-start gap-2">
                                  <span className="w-5 h-5 rounded-full bg-teal-600 text-white text-[11px] font-bold flex items-center justify-center shrink-0 mt-0.5">
                                    {i + 1}
                                  </span>
                                  <p className="text-xs sm:text-sm text-slate-800 leading-relaxed">
                                    {step}
                                  </p>
                                </div>
                              ))}
                            </div>
                          ) : (
                            <p className="text-xs text-slate-500">등록된 감별 흐름도가 없습니다.</p>
                          )}
                        </div>

                        {/* 붉은색 경고 박스 (redFlag) */}
                        {card.redFlag && (
                          <div className="bg-red-50 border border-red-200 rounded-xl p-3 flex items-start gap-2.5">
                            <AlertTriangle className="w-4 h-4 text-red-600 shrink-0 mt-0.5" />
                            <div>
                              <p className="text-xs font-bold text-red-800 mb-0.5">
                                Red Flag (즉시 병원 의뢰 경고)
                              </p>
                              <p className="text-xs sm:text-sm text-red-700 leading-relaxed">
                                {card.redFlag}
                              </p>
                            </div>
                          </div>
                        )}

                        {/* 주성분 & 병용금기 */}
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                          <div className="bg-teal-50/60 border border-teal-100 rounded-xl p-3">
                            <div className="flex items-center gap-1.5 text-xs font-bold text-teal-800 mb-1">
                              <Pill className="w-3.5 h-3.5" />
                              <span>주성분</span>
                            </div>
                            <p className="text-xs sm:text-sm text-slate-800 leading-relaxed">
                              {card.mainIngredient}
                            </p>
                          </div>

                          <div className="bg-amber-50/70 border border-amber-200/80 rounded-xl p-3">
                            <div className="flex items-center gap-1.5 text-xs font-bold text-amber-900 mb-1">
                              <ShieldAlert className="w-3.5 h-3.5 text-amber-600" />
                              <span>병용금기 · 주의</span>
                            </div>
                            <p className="text-xs sm:text-sm text-slate-800 leading-relaxed">
                              {card.contraindications}
                            </p>
                          </div>
                        </div>

                        {/* 복약지도 멘트 */}
                        <div className="bg-indigo-50/60 border border-indigo-100 rounded-xl p-3">
                          <div className="flex items-center gap-1.5 text-xs font-bold text-indigo-800 mb-1">
                            <MessageSquareHeart className="w-3.5 h-3.5" />
                            <span>복약지도 멘트</span>
                          </div>
                          <p className="text-xs sm:text-sm text-slate-800 leading-relaxed">
                            {card.counseling}
                          </p>
                        </div>
                      </div>
                    )}
                  </article>
                );
              })}
            </div>
          </section>
        )}

        {/* ================================================================
            2. 플래시카드 암기 모드 ('국시 카드' 스타일)
           ================================================================ */}
        {activeTab === 'flashcard' && (
          <section className="space-y-4">
            {/* 필터 & 오늘 본 카드 수 */}
            <div className="bg-white rounded-2xl border border-slate-200 p-3 space-y-3 shadow-sm">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="flex items-center gap-2">
                  <select
                    value={fcChapter}
                    onChange={(e) => setFcChapter(e.target.value)}
                    aria-label="대단원 필터"
                    className="text-xs sm:text-sm font-semibold bg-slate-50 border border-slate-200 rounded-xl px-3 py-1.5 text-slate-700 focus:outline-none focus:ring-2 focus:ring-teal-500"
                  >
                    {chapters.map((ch) => (
                      <option key={ch} value={ch}>
                        {ch === '전체' ? '전체 대단원' : ch}
                      </option>
                    ))}
                  </select>

                  <button
                    type="button"
                    onClick={() => setOnlyStarred((prev) => !prev)}
                    className={`inline-flex items-center gap-1 px-3 py-1.5 rounded-xl text-xs font-semibold border transition-colors ${
                      onlyStarred
                        ? 'bg-amber-50 border-amber-300 text-amber-700'
                        : 'bg-slate-50 border-slate-200 text-slate-600 hover:bg-slate-100'
                    }`}
                  >
                    <Star
                      className={`w-3.5 h-3.5 ${
                        onlyStarred ? 'fill-amber-400 text-amber-500' : 'text-slate-400'
                      }`}
                    />
                    <span>다시보기(★)만</span>
                  </button>
                </div>

                <div className="text-xs font-semibold text-slate-600">
                  오늘 본 카드{' '}
                  <span className="text-teal-700 font-bold">
                    {dailyViewData.viewedIds.length}
                  </span>
                  장
                </div>
              </div>

              {/* 상단 진행률 바 (1 / N) */}
              <div>
                <div className="flex items-center justify-between text-xs font-semibold text-slate-500 mb-1">
                  <span>진행률</span>
                  <span className="text-slate-800">
                    {flashcardPool.length > 0 ? `${fcIndex + 1} / ${flashcardPool.length}` : '0 / 0'}
                  </span>
                </div>
                <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                  <div
                    className="h-full bg-teal-600 rounded-full transition-all duration-300"
                    style={{
                      width:
                        flashcardPool.length > 0
                          ? `${((fcIndex + 1) / flashcardPool.length) * 100}%`
                          : '0%',
                    }}
                  />
                </div>
              </div>
            </div>

            {/* 카드 본문 */}
            {currentFlashcard ? (
              <div className="space-y-3">
                <div
                  onClick={handleFlipCard}
                  role="button"
                  tabIndex={0}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      handleFlipCard();
                    }
                  }}
                  className="cursor-pointer select-none"
                >
                  <div
                    className={`relative rounded-3xl border shadow-md transition-all duration-300 p-5 sm:p-6 min-h-[360px] flex flex-col justify-between ${
                      isFlipped
                        ? 'bg-slate-900 text-white border-slate-800'
                        : 'bg-white text-slate-900 border-slate-200'
                    }`}
                  >
                    {/* 카드 상단 배지 */}
                    <div className="flex items-center justify-between gap-2 mb-4">
                      <div className="flex flex-wrap items-center gap-1.5">
                        <span
                          className={`text-[11px] font-bold px-2.5 py-0.5 rounded-full ${
                            isFlipped
                              ? 'bg-teal-500/20 text-teal-300 border border-teal-500/30'
                              : 'bg-teal-50 text-teal-700 border border-teal-100'
                          }`}
                        >
                          {currentFlashcard.chapter}
                        </span>
                        <span
                          className={`text-[11px] font-semibold px-2.5 py-0.5 rounded-full ${
                            isFlipped
                              ? 'bg-slate-800 text-slate-300'
                              : 'bg-slate-100 text-slate-600'
                          }`}
                        >
                          {currentFlashcard.subCategory}
                        </span>
                      </div>

                      <span
                        className={`inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-full ${
                          isFlipped ? 'bg-slate-800 text-slate-300' : 'bg-slate-100 text-slate-500'
                        }`}
                      >
                        <RotateCw className="w-3 h-3" />
                        {isFlipped ? '뒷면 (해설)' : '앞면 (문제)'}
                      </span>
                    </div>

                    {/* 앞면: 질문 & 힌트 */}
                    {!isFlipped ? (
                      <div className="flex-1 flex flex-col justify-center py-4 space-y-5">
                        <div>
                          <p className="text-xs font-bold uppercase tracking-wider text-teal-600 mb-2">
                            국시 실전 포인트
                          </p>
                          <h2 className="text-lg sm:text-xl font-bold text-slate-900 leading-relaxed">
                            {currentFlashcard.question}
                          </h2>
                        </div>

                        <div>
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              setShowHint((prev) => !prev);
                            }}
                            className="inline-flex items-center gap-1.5 text-xs font-semibold text-amber-700 bg-amber-50 border border-amber-200 px-3 py-1.5 rounded-xl hover:bg-amber-100 transition-colors"
                          >
                            <Sparkles className="w-3.5 h-3.5" />
                            <span>{showHint ? '힌트 숨기기' : '힌트 보기'}</span>
                          </button>
                          {showHint && (
                            <p className="mt-2.5 text-sm text-slate-600 bg-slate-50 border border-slate-200 rounded-xl p-3 leading-relaxed">
                              💡 {currentFlashcard.hint}
                            </p>
                          )}
                        </div>
                      </div>
                    ) : (
                      /* 뒷면: 알고리즘 경로 · 주성분 · 기전 · 병용금기 · 복약지도 */
                      <div className="flex-1 space-y-3 text-left">
                        {currentFlashcard.algorithmFlow.length > 0 && (
                          <div className="bg-slate-800/80 rounded-xl p-3 border border-slate-700">
                            <p className="text-[11px] font-bold text-teal-300 mb-1">
                              알고리즘 경로
                            </p>
                            <p className="text-xs sm:text-sm text-slate-100 leading-relaxed">
                              {currentFlashcard.algorithmFlow.join(' → ')}
                            </p>
                          </div>
                        )}

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                          <div className="bg-slate-800/80 rounded-xl p-3 border border-slate-700">
                            <p className="text-[11px] font-bold text-emerald-300 mb-1">주성분</p>
                            <p className="text-xs sm:text-sm text-slate-100 leading-relaxed">
                              {currentFlashcard.mainIngredient}
                            </p>
                          </div>
                          <div className="bg-slate-800/80 rounded-xl p-3 border border-slate-700">
                            <p className="text-[11px] font-bold text-sky-300 mb-1">약리 기전</p>
                            <p className="text-xs sm:text-sm text-slate-100 leading-relaxed">
                              {currentFlashcard.mechanism}
                            </p>
                          </div>
                        </div>

                        <div className="bg-amber-500/10 rounded-xl p-3 border border-amber-500/30">
                          <p className="text-[11px] font-bold text-amber-300 mb-1">병용금기 · 주의</p>
                          <p className="text-xs sm:text-sm text-amber-100 leading-relaxed">
                            {currentFlashcard.contraindications}
                          </p>
                        </div>

                        <div className="bg-indigo-500/15 rounded-xl p-3 border border-indigo-400/30">
                          <p className="text-[11px] font-bold text-indigo-300 mb-1">복약지도 멘트</p>
                          <p className="text-xs sm:text-sm text-indigo-100 leading-relaxed">
                            {currentFlashcard.counseling}
                          </p>
                        </div>

                        {currentFlashcard.redFlag && (
                          <div className="bg-red-500/15 rounded-xl p-3 border border-red-500/40">
                            <p className="text-[11px] font-bold text-red-300 mb-0.5">Red Flag</p>
                            <p className="text-xs text-red-100 leading-relaxed">
                              {currentFlashcard.redFlag}
                            </p>
                          </div>
                        )}
                      </div>
                    )}

                    {/* 카드 하단 안내 */}
                    <div
                      className={`mt-4 pt-3 border-t flex items-center justify-between text-xs ${
                        isFlipped ? 'border-slate-800 text-slate-400' : 'border-slate-100 text-slate-400'
                      }`}
                    >
                      <span>카드를 탭하면 {isFlipped ? '앞면으로' : '정답·해설로'} 뒤집힙니다</span>
                    </div>
                  </div>
                </div>

                {/* 하단 액션 컨트롤: 이전 / 다시보기 / 암기완료 / 다음 */}
                <div className="grid grid-cols-4 gap-2">
                  <button
                    type="button"
                    onClick={handlePrevCard}
                    className="py-3 px-2 rounded-2xl bg-white border border-slate-200 text-slate-700 font-semibold text-xs flex items-center justify-center gap-1 hover:bg-slate-50 active:scale-95 transition"
                  >
                    <ChevronLeft className="w-4 h-4" />
                    <span>이전</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => toggleStar(currentFlashcard.id)}
                    className={`py-3 px-2 rounded-2xl border font-semibold text-xs flex items-center justify-center gap-1 active:scale-95 transition ${
                      starredSet.has(currentFlashcard.id)
                        ? 'bg-amber-50 border-amber-300 text-amber-700'
                        : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                    }`}
                  >
                    <Star
                      className={`w-4 h-4 ${
                        starredSet.has(currentFlashcard.id) ? 'fill-amber-400 text-amber-500' : ''
                      }`}
                    />
                    <span>다시보기</span>
                  </button>

                  <button
                    type="button"
                    onClick={() => toggleMastered(currentFlashcard.id)}
                    className={`py-3 px-2 rounded-2xl border font-semibold text-xs flex items-center justify-center gap-1 active:scale-95 transition ${
                      masteredSet.has(currentFlashcard.id)
                        ? 'bg-emerald-50 border-emerald-300 text-emerald-700'
                        : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'
                    }`}
                  >
                    <CheckCircle2 className="w-4 h-4" />
                    <span>암기완료</span>
                  </button>

                  <button
                    type="button"
                    onClick={handleNextCard}
                    className="py-3 px-2 rounded-2xl bg-teal-600 text-white font-semibold text-xs flex items-center justify-center gap-1 hover:bg-teal-700 active:scale-95 transition shadow-sm"
                  >
                    <span>다음</span>
                    <ChevronRight className="w-4 h-4" />
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-white rounded-2xl border border-slate-200 p-8 text-center space-y-2">
                <Star className="w-8 h-8 text-amber-400 mx-auto" />
                <p className="text-sm font-bold text-slate-800">
                  조건에 맞는 플래시카드가 없습니다.
                </p>
                <p className="text-xs text-slate-500">
                  다시보기(★) 필터를 해제하거나 다른 대단원을 선택해 보세요.
                </p>
              </div>
            )}
          </section>
        )}

        {/* ================================================================
            3. 성분·증상 검색 탭
           ================================================================ */}
        {activeTab === 'search' && (
          <section className="space-y-4">
            <div className="relative">
              <Search className="w-4 h-4 text-slate-400 absolute left-3.5 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="주성분, 증상, 병용금기, 질환명 검색 (예: Oxymetazoline, 속쓰림)"
                className="w-full pl-10 pr-10 py-3 rounded-2xl bg-white border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500 shadow-sm"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  aria-label="검색어 지우기"
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-1 text-slate-400 hover:text-slate-600"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>

            <div className="flex items-center justify-between text-xs text-slate-500 px-1">
              <span>검색 결과 {searchResults.length}건</span>
              <span>카드를 누르면 상세 내용을 봅니다</span>
            </div>

            <div className="space-y-2.5">
              {searchResults.map((card) => (
                <button
                  key={card.id}
                  type="button"
                  onClick={() => setSelectedSearchCard(card)}
                  className="w-full text-left bg-white rounded-2xl border border-slate-200 p-4 hover:border-teal-300 hover:shadow-sm transition-all"
                >
                  <div className="flex items-center justify-between gap-2 mb-1">
                    <span className="text-[11px] font-semibold px-2 py-0.5 rounded-md bg-teal-50 text-teal-700">
                      {card.chapter}
                    </span>
                    <div className="flex items-center gap-1">
                      {starredSet.has(card.id) && (
                        <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-500" />
                      )}
                      {masteredSet.has(card.id) && (
                        <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" />
                      )}
                    </div>
                  </div>
                  <h3 className="text-sm font-bold text-slate-900">{card.subCategory}</h3>
                  <p className="text-xs text-teal-700 font-medium mt-1">
                    주성분: {card.mainIngredient}
                  </p>
                  <p className="text-xs text-slate-500 mt-1 line-clamp-2">
                    금기/주의: {card.contraindications}
                  </p>
                </button>
              ))}
              {searchResults.length === 0 && (
                <div className="bg-white rounded-2xl border border-slate-200 p-8 text-center text-sm text-slate-500">
                  일치하는 성분이나 증상이 없습니다.
                </div>
              )}
            </div>
          </section>
        )}

        {/* ================================================================
            4. JSON 추가/백업 탭
           ================================================================ */}
        {activeTab === 'backup' && (
          <section className="space-y-4">
            {/* JSON 데이터 이어붙이기 */}
            <div className="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
              <div className="flex items-center justify-between">
                <h2 className="text-sm font-bold text-slate-900 flex items-center gap-1.5">
                  <PlusCircle className="w-4 h-4 text-teal-600" />
                  <span>JSON 카드 데이터 추가</span>
                </h2>
                <span className="text-[11px] text-slate-500">
                  추가된 카드: {customCards.length}장
                </span>
              </div>
              <p className="text-xs text-slate-600 leading-relaxed">
                나머지 8개 파일에서 추출한 JSON 배열(<code className="bg-slate-100 px-1 rounded">[&#123;...&#125;]</code>)을
                여기에 붙여넣으면 즉시 앱에 반영되고 브라우저에 저장됩니다.
              </p>

              <div className="flex items-center gap-2 text-xs">
                <button
                  type="button"
                  onClick={() => setImportMode('append')}
                  className={`px-3 py-1.5 rounded-xl font-semibold border ${
                    importMode === 'append'
                      ? 'bg-teal-50 border-teal-300 text-teal-700'
                      : 'bg-slate-50 border-slate-200 text-slate-600'
                  }`}
                >
                  기존 목록에 이어붙이기
                </button>
                <button
                  type="button"
                  onClick={() => setImportMode('replace')}
                  className={`px-3 py-1.5 rounded-xl font-semibold border ${
                    importMode === 'replace'
                      ? 'bg-teal-50 border-teal-300 text-teal-700'
                      : 'bg-slate-50 border-slate-200 text-slate-600'
                  }`}
                >
                  추가 데이터만 새로 덮어쓰기
                </button>
              </div>

              <textarea
                rows={6}
                value={jsonInput}
                onChange={(e) => setJsonInput(e.target.value)}
                placeholder='[{"chapter": "심혈관계", "subCategory": "고혈압", "question": "...", "algorithmFlow": ["..."], "redFlag": "...", "mainIngredient": "...", "mechanism": "...", "contraindications": "...", "counseling": "..."}]'
                className="w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-xs font-mono focus:outline-none focus:ring-2 focus:ring-teal-500"
              />

              <button
                type="button"
                onClick={handleImportJson}
                className="w-full py-2.5 rounded-xl bg-teal-600 text-white text-sm font-semibold hover:bg-teal-700 transition-colors"
              >
                JSON 데이터 적용하기
              </button>
            </div>

            {/* 백업 & 내보내기 */}
            <div className="bg-white rounded-2xl border border-slate-200 p-4 space-y-3 shadow-sm">
              <h2 className="text-sm font-bold text-slate-900">데이터 및 학습 기록 백업</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2.5">
                <button
                  type="button"
                  onClick={handleCopyAllJson}
                  className="py-2.5 px-3 rounded-xl border border-slate-200 bg-slate-50 text-slate-700 text-xs font-semibold flex items-center justify-center gap-1.5 hover:bg-slate-100"
                >
                  <Copy className="w-4 h-4" />
                  <span>전체 카드 JSON 복사</span>
                </button>
                <button
                  type="button"
                  onClick={handleDownloadBackup}
                  className="py-2.5 px-3 rounded-xl border border-teal-200 bg-teal-50 text-teal-700 text-xs font-semibold flex items-center justify-center gap-1.5 hover:bg-teal-100"
                >
                  <Download className="w-4 h-4" />
                  <span>전체 백업 파일(.json) 저장</span>
                </button>
              </div>

              <div className="pt-2 border-t border-slate-100 flex items-center justify-between">
                <span className="text-xs text-slate-500">
                  다시보기(★) 및 암기완료(✓) 기록 초기화
                </span>
                <button
                  type="button"
                  onClick={() => setConfirmResetOpen(true)}
                  className="inline-flex items-center gap-1 text-xs font-semibold text-red-600 hover:text-red-700 px-2.5 py-1.5 rounded-lg hover:bg-red-50"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                  <span>학습 기록 초기화</span>
                </button>
              </div>
            </div>
          </section>
        )}
      </main>

      {/* 검색 결과 상세 모달 */}
      {selectedSearchCard && (
        <div
          className="fixed inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-end sm:items-center justify-center p-0 sm:p-4"
          onClick={() => setSelectedSearchCard(null)}
        >
          <div
            className="bg-white w-full max-w-lg rounded-t-3xl sm:rounded-3xl p-5 max-h-[85vh] overflow-y-auto space-y-3 shadow-xl"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex items-start justify-between gap-2">
              <div>
                <span className="text-[11px] font-semibold px-2 py-0.5 rounded-md bg-teal-50 text-teal-700">
                  {selectedSearchCard.chapter}
                </span>
                <h3 className="text-lg font-bold text-slate-900 mt-1">
                  {selectedSearchCard.subCategory}
                </h3>
              </div>
              <button
                type="button"
                onClick={() => setSelectedSearchCard(null)}
                className="p-1.5 rounded-full bg-slate-100 text-slate-500 hover:text-slate-800"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {selectedSearchCard.redFlag && (
              <div className="bg-red-50 border border-red-200 rounded-xl p-3 text-xs text-red-700">
                <strong className="block text-red-800 mb-0.5">Red Flag</strong>
                {selectedSearchCard.redFlag}
              </div>
            )}

            <div className="bg-slate-50 rounded-xl p-3 border border-slate-200 text-xs space-y-1">
              <strong className="block text-slate-700">감별 흐름도</strong>
              <p className="text-slate-800 leading-relaxed">
                {selectedSearchCard.algorithmFlow.join(' → ')}
              </p>
            </div>

            <div className="text-xs space-y-2">
              <div className="bg-teal-50/60 p-3 rounded-xl border border-teal-100">
                <strong className="block text-teal-800 mb-0.5">주성분</strong>
                <p className="text-slate-800">{selectedSearchCard.mainIngredient}</p>
              </div>
              <div className="bg-slate-50 p-3 rounded-xl border border-slate-200">
                <strong className="block text-slate-700 mb-0.5">약리 기전</strong>
                <p className="text-slate-800">{selectedSearchCard.mechanism}</p>
              </div>
              <div className="bg-amber-50 p-3 rounded-xl border border-amber-200">
                <strong className="block text-amber-900 mb-0.5">병용금기 · 주의</strong>
                <p className="text-slate-800">{selectedSearchCard.contraindications}</p>
              </div>
              <div className="bg-indigo-50 p-3 rounded-xl border border-indigo-100">
                <strong className="block text-indigo-900 mb-0.5">복약지도 멘트</strong>
                <p className="text-slate-800">{selectedSearchCard.counseling}</p>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 초기화 확인 모달 (window.confirm 대체) */}
      {confirmResetOpen && (
        <div
          className="fixed inset-0 z-50 bg-slate-900/50 backdrop-blur-sm flex items-center justify-center p-4"
          onClick={() => setConfirmResetOpen(false)}
        >
          <div
            className="bg-white w-full max-w-sm rounded-2xl p-5 space-y-4 shadow-xl"
            onClick={(e) => e.stopPropagation()}
          >
            <h3 className="text-base font-bold text-slate-900">학습 기록을 초기화할까요?</h3>
            <p className="text-xs text-slate-600 leading-relaxed">
              저장된 다시보기(★), 암기완료(✓), 오늘 본 카드 수 기록이 모두 삭제됩니다.
            </p>
            <div className="flex items-center justify-end gap-2">
              <button
                type="button"
                onClick={() => setConfirmResetOpen(false)}
                className="px-3.5 py-2 rounded-xl text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200"
              >
                취소
              </button>
              <button
                type="button"
                onClick={handleResetProgress}
                className="px-3.5 py-2 rounded-xl text-xs font-semibold bg-red-600 text-white hover:bg-red-700"
              >
                초기화
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 하단 고정 내비게이션 바 (4개 탭) */}
      <nav className="fixed bottom-0 inset-x-0 z-40 bg-white/95 backdrop-blur border-t border-slate-200">
        <div className="max-w-2xl mx-auto grid grid-cols-4">
          {[
            { id: 'algorithm', label: '알고리즘', icon: GitBranch },
            { id: 'flashcard', label: '플래시카드', icon: Layers },
            { id: 'search', label: '성분·증상 검색', icon: Search },
            { id: 'backup', label: 'JSON 추가/백업', icon: Database },
          ].map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => setActiveTab(tab.id)}
                className={`py-2.5 px-1 flex flex-col items-center justify-center gap-1 text-[11px] font-semibold transition-colors ${
                  isActive ? 'text-teal-600' : 'text-slate-500 hover:text-slate-800'
                }`}
              >
                <Icon className={`w-5 h-5 ${isActive ? 'stroke-[2.5]' : ''}`} />
                <span className="truncate max-w-full">{tab.label}</span>
              </button>
            );
          })}
        </div>
      </nav>
    </div>
  );
}